			Key("session.id").
			Int(int(reqContext.SessionID)),
	)
	defer span.End()

	// parse the message body
	var dispatchReq DispatchRequest
	err = json.Unmarshal(msg.Value, &dispatchReq)
	if err != nil {
		consumer.logger.For(ctx).Error("error decoding message body")
		span.SetStatus(codes.Error, err.Error())
		return
	}

	// send a notification
	notificationCtx := consumer.notification.NotificationContext(
		reqContext, baggageutils.GetRoutingKey(ctx))
	consumer.notification.Store(ctx, &notifications.Notification{
		ID:        fmt.Sprintf("req-%d-finding-driver", reqContext.ID),
		Timestamp: time.Now(),
		Context:   notificationCtx,
		Body:      "Finding an available driver",
	})

	// find availanble drivers
	driverIDs := consumer.driverStore.FindDriverIDs(ctx)

	// populate current driver's locations
	drivers, err := consumer.driverStore.GetDriversLocation(ctx, driverIDs)
	if err != nil {
		span.SetStatus(codes.Error, err.Error())
		return
	}

	// get the driver with the best ETA
	bestDriver, err := consumer.bestETA.Get(ctx, &dispatchReq, drivers)
	if err != nil {
		consumer.logger.For(ctx).Error("error calculating best route", zap.Error(err))
		span.SetStatus(codes.Error, err.Error())
		return
	}

	// send a notification
	consumer.notification.Store(ctx, &notifications.Notification{
		ID:        fmt.Sprintf("req-%d-dispatched-driver", reqContext.ID),
		Timestamp: time.Now(),
		Context:   notificationCtx,
		Body:      fmt.Sprintf("Driver %s arriving in %s", bestDriver.DriverID, bestDriver.ETA.String()),
	})
}
package driver

import (
	"github.com/signadot/hotrod/services/location"
)

type DispatchRequest struct {
	PickupLocation  *location.Location `json:"pickupLocation"`
	DropoffLocation *location.Location `json:"dropoffLocation"`
}

type Driver struct {
	DriverID    string
	Coordinates string
}
	}

	d.logger.For(ctx).Info("Found locations", zap.Any("pickupLocation", pickupLoc),
		zap.Any("dropoffLocation", dropoffLoc))
	return pickupLoc, dropoffLoc, nil
}

func (d *dispatcher) DispatchDriver(ctx context.Context, req *DispatchRequest,
	pickupLoc, dropoffLoc *location.Location) error {
	ctx, span := d.tracer.Start(ctx, "DispatchDriver", trace.WithSpanKind(trace.SpanKindClient))
	span.SetAttributes(
		attribute.
			Key("session.id").
			Int(int(req.SessionID)),
	)
	defer span.End()

	driverRequest := driver.DispatchRequest{
		PickupLocation:  pickupLoc,
		DropoffLocation: dropoffLoc,
	}
	msgBody, err := json.Marshal(driverRequest)
	if err != nil {
		return fmt.Errorf("couldn't encode driver request, %w", err)
	}

	msg := &sarama.ProducerMessage{
		Topic: kafka.DispatchDriverTopic,
		Key:   sarama.StringEncoder("message"),
		Value: sarama.StringEncoder(string(msgBody)),
	}
	otel.GetTextMapPropagator().Inject(ctx, otelsarama.NewProducerMessageCarrier(msg))

	partition, offset, err := d.producer.SendMessage(msg)
	if err != nil {
		return fmt.Errorf("couldn't publish message to kafka, %w", err)
	}

	d.logger.For(ctx).Info("Published message to kafka",
		zap.Any("pickupLocation", pickupLoc),
		zap.Any("dropoffLocation", dropoffLoc),
		zap.Any("partition", partition),
		zap.Any("offset", offset),
	)
	return nil
}
// getRoutes calls Route service for each pick location, driver location pair
func (eta *bestETA) getRoutes(ctx context.Context, pickupLoc *location.Location,
	drivers []*Driver) []routeResult {
	results := make([]routeResult, 0, len(drivers))
	wg := sync.WaitGroup{}
	routesLock := sync.Mutex{}

	for _, dd := range drivers {
		wg.Add(1)
		driver := dd // capture loop var
		// Use worker pool to (potentially) execute requests in parallel
		eta.pool.Execute(func() {
			route, err := eta.route.FindRoute(ctx, driver.Coordinates, pickupLoc.Coordinates)
			routesLock.Lock()
			results = append(results, routeResult{
				driverID: driver.DriverID,
				route:    route,
				err:      err,
			})
			routesLock.Unlock()
			wg.Done()
		})
	}
	wg.Wait()
	return results
}
